"""Photographic editorial layouts. Source content remains in the data files."""
from html import escape
from urllib.parse import quote
import re
from enrichment import stars, recommend
def e(s):return escape(str(s or ''),quote=True)
def img(f,pre='',large=False,cls=''):
 return f'<img class="{cls}" src="{pre}{e(f["image"] if large else f["thumbnail"])}" alt="{e(f["name"])} — {"documentary photograph" if f["image_kind"]=="photograph" else "illustration; photography not yet available"}" width="1600" height="1000" '+('fetchpriority="high"' if large else 'loading="lazy" decoding="async"')+'>'
def label(f):return 'Documentary photograph' if f['image_kind']=='photograph' else 'Illustration · photo pending'
def credit(p):
 return e(p.get('artist',''))+' · <a href="'+e(p['source'])+'">Original source</a> · '+('<a href="'+e(p['license_url'])+'">'+e(p['license'])+'</a>' if p.get('license_url') else e(p.get('license','Permission recorded')))
def card(f,pre=''):
 return f'''<article class="fort-card" data-fort="{e(f['slug'])}" data-tilt><a class="card-image" href="{pre}{f['url']}">{img(f,pre)}<span class="photo-label">{label(f)}</span><span class="card-arrow" aria-hidden="true">↗</span></a><div class="card-body"><p class="card-location">{e(f['district'])} <span>·</span> {e(f['type'])}</p><h3><a href="{pre}{f['url']}">{e(f['name'])}</a></h3><p>{e(f['significance'][:140].rsplit(' ',1)[0]+'…' if len(f['significance'])>140 else f['significance'])}</p><div class="card-assessment">{stars(f)}{recommend(f)}</div><div class="card-bottom"><a href="{pre}{f['url']}">Explore fort ↗</a><a href="{pre}maps.html?fort={f['slug']}" aria-label="Locate {e(f['name'])} on map">View on map ⌖</a></div></div></article>'''
def heading(kicker,title,link='',url=''):
 return '<div class="section-heading"><div><p class="eyebrow">'+kicker+'</p><h2>'+title+'</h2></div>'+('<a class="outline-button" href="'+url+'">'+link+' ↗</a>' if link else '')+'</div>'
def home(data,gallery,events):
 by={f['slug']:f for f in data};hero=by['rajgad'];raigad=by['raigad'];sea=by['sindhudurg-fort'];hills=by['harishchandragad']
 featured=[by[s] for s in ['raigad','rajgad','pratapgad','sindhudurg-fort','harishchandragad','harihar'] if s in by]
 photos=sum(len(ps) for ps in gallery.values())
 out=f'''<section class="cinema-hero" data-spotlight><div class="cinema-photo" data-parallax>{img(hero,large=True)}</div><div class="cinema-scrim"></div><div class="wrap cinema-content"><p class="eyebrow">SWARAJYA EXPLORER / MAHARASHTRA, INDIA</p><h1>Some stories<br>are written<br><em>in stone.</em></h1><p>Walk the ridges. Follow the sea walls.<br>Discover the forts that shaped Swarajya.</p><div class="hero-actions"><a class="button" data-magnetic href="forts.html">Find your next fort <span>↗</span></a><a class="text-button" href="history.html">Journey through history →</a></div><form class="cinema-search" action="forts.html" role="search"><label for="home-search">Where does your journey begin?</label><div><span aria-hidden="true">⌕</span><input id="home-search" name="q" type="search" placeholder="Fort, district or nearby city" list="fort-suggestions"><datalist id="fort-suggestions">{''.join('<option value="'+e(f['name'])+'">' for f in data)}</datalist><button type="submit" aria-label="Search forts">Explore ↗</button></div></form></div><a class="hero-location" href="{hero['url']}"><span>IN THE FRAME</span><strong>Rajgad, Pune</strong><small>A capital in the clouds ↗</small></a><span class="hero-scroll" aria-hidden="true">SCROLL TO EXPLORE ↓</span></section>
<section class="discovery-strip"><div class="wrap"><p><strong data-count="{len(data)}">{len(data)}</strong> fort stories</p><p><strong data-count="{len(set(f['district'] for f in data))}">{len(set(f['district'] for f in data))}</strong> districts</p><p><strong data-count="{photos}">{photos}</strong> gallery photographs</p><a href="about.html">Independent heritage exploration ↗</a></div></section>
<section class="wrap section editorial-intro"><div class="image-stack" data-reveal="image">{img(raigad)}<span class="image-note">01 / RAIGAD · THE ROYAL CAPITAL</span><a href="{sea['url']}" class="stack-inset">{img(sea)}<span>02 / SINDHUDURG ↗</span></a></div><div data-reveal="slide"><p class="eyebrow">BEYOND THE POSTCARD</p><h2>A landscape.<br>A legacy.<br><em>A thousand stories.</em></h2><p>High on a Sahyadri ridge, a gateway still frames the valley. On the Konkan coast, walls rise straight from the sea. Every fort offers a different way into Maharashtra’s past.</p><p>Explore the places associated with Chhatrapati Shivaji Maharaj, Chhatrapati Sambhaji Maharaj and the many generations who built, defended and cared for them.</p><a class="text-button" href="history.html">Meet the history behind the landscape <span>↗</span></a></div></section>
<section class="wrap section">{heading('BEGIN WITH THE EXTRAORDINARY','Six places. <em>Endless discovery.</em>','All forts','forts.html')}<div class="card-grid">{''.join(card(f) for f in featured)}</div></section>
<section class="wrap section">{heading('FORTS, PEOPLE & TURNING POINTS','A journey through <em>Swarajya.</em>','Full timeline','history.html')}<div class="story-rail">'''
 for ev in [next((x for x in events if x['id']==key),None) for key in ['torna-beginnings','pratapgad-1659','raigad-coronation-1674']]:
  if not ev:continue
  fort=next((by[s] for s in ev['fort_slugs'] if s in by),raigad)
  out+=f'<a class="story-tile" href="history.html#{e(ev["id"])}">{img(fort)}<div><span>{e(ev["date"])}</span><h3>{e(ev["title"])}</h3><p>{e(ev["significance"])}</p><b>Read the story ↗</b></div></a>'
 out+='</div></section><section class="wrap section district-discovery">'+heading('CHOOSE YOUR LANDSCAPE','Mountains, coast <em>& country.</em>','Explore districts','districts.html')+'<div class="region-grid">'
 for district,s,caption in [('Pune','sinhagad','The heart of the Maval country'),('Raigad','raigad','Capitals, passes and sea walls'),('Nashik','salher','High peaks of the northern Sahyadris')]:
  if s not in by:continue
  out+=f'<a href="districts/{district.lower()}/index.html" class="region-tile" data-reveal="image">{img(by[s])}<div><span>{sum(f["district"]==district for f in data)} FORTS</span><h3>{district} ↗</h3><p>{caption}</p></div></a>'
 out+='</div></section><section class="photo-editorial"><div class="wrap">'+heading('LOOK A LITTLE CLOSER','Details that <em>hold history.</em>','Photo journal','gallery.html')+'<div class="journal-grid">'
 for s in ['sinhagad','vijaydurg-fort','lohagad','visapur-fort']:
  if s in by:out+=f'<a href="{by[s]["url"]}#fort-gallery">{img(by[s])}<span>{e(by[s]["name"])} <b>↗</b></span></a>'
 out+='</div></div></section><section class="wrap section trail-section">'+heading('FIND YOUR PACE','A little walk.<br><em>A bigger adventure.</em>')+'<div class="trail-links">'
 for n,desc in [('Easy','A gentler introduction'),('Moderate','A rewarding ascent'),('Difficult','For experienced explorers')]:out+=f'<a href="forts.html?difficulty={n}"><span>0{["Easy","Moderate","Difficult"].index(n)+1}</span><div><h3>{n}</h3><p>{desc}</p></div><b>↗</b></a>'
 out+='</div><p class="small">Source-based trek grades are provisional. Read the route explanation and check current conditions before travelling.</p></section><section class="creator-band"><div class="wrap"><p class="eyebrow">MADE WITH A LOVE FOR MAHARASHTRA</p><h2>Explore thoughtfully.<br><em>Keep the stories alive.</em></h2><p>An independent project by Pranav Vinod Chame.<br>Inspired by Tanshiq and Karan.</p><a class="outline-button" href="about.html">Our story ↗</a><a class="text-button" href="https://www.instagram.com/pranavdecoded/">Follow the journey ↗</a></div></section>'
 return out
def story(ev,by,pre=''):
 related=[by[s] for s in ev.get('fort_slugs',[]) if s in by];f=related[0] if related else None
 year=ev.get('year') or (int(re.search(r'\d{4}',ev['date'])[0]) if re.search(r'\d{4}',ev['date']) else 0)
 era=ev.get('era') or ('Early Swarajya' if year<1680 else 'Resistance & renewal' if year<1720 else 'Expansion & legacy')
 return f'''<article class="history-entry" id="{e(ev['id'])}" data-era="{e(era)}" data-year="{year}"><div class="history-date"><span>{e(ev['date'])}</span><i aria-hidden="true"></i></div><div class="history-content">{('<a class="history-photo" href="'+pre+f['url']+'">'+img(f,pre)+'<span>Explore '+e(f['name'])+' ↗</span></a>') if f else ''}<p class="eyebrow">{e(era)}</p><h2>{e(ev['title'])}</h2><div class="story-preview"><p>{e(' '.join(ev['summary'][:10]))}</p></div><details><summary>Read full story <span aria-hidden="true">＋</span></summary><div class="story-expanded">{('<p class="story-people"><b>People:</b> '+e(', '.join(ev['people']) if isinstance(ev.get('people'),list) else ev.get('people',''))+'</p>') if ev.get('people') else ''}{''.join('<p>'+e(p)+'</p>' for p in ev['full'])}<div class="related-story-links">{''.join('<a href="'+pre+f['url']+'">'+e(f['name'])+' ↗</a>' for f in related)}</div><p class="small">Sources: {', '.join('<a href="'+e(r['url'])+'">'+e(r['title'])+'</a>' for r in ev['references'])}</p></div></details></div></article>'''
def history(data,events):
 by={f['slug']:f for f in data};evs=sorted(events,key=lambda ev:ev.get('year') or (int(re.search(r'\d{4}',ev['date'])[0]) if re.search(r'\d{4}',ev['date']) else 0))
 eras=list(dict.fromkeys(ev.get('era') or 'Early Swarajya' for ev in evs))
 return '<section class="history-mast"><div class="wrap"><p class="eyebrow">स्वराज्य / A LIVING HISTORY</p><h1>From a vision<br>to a <em>lasting legacy.</em></h1><p>The people, places and turning points of the Maratha state.<br>Explore the story in chronological order, one chapter at a time.</p><div class="history-stat">'+str(len(events))+' sourced chapters <span>·</span> forts connected to their stories</div></div></section>'+'<section class="wrap history-explorer"><form id="history-filter" class="history-filter" role="search"><label>Find a story<input type="search" name="historyq" placeholder="Try Sambhaji, coronation or 1674"></label><label>Choose an era<select name="era"><option value="">All eras</option>'+''.join('<option>'+e(era)+'</option>' for era in eras)+'</select></label><button type="reset" class="outline-button">Reset</button><p id="history-count" role="status"></p></form><div class="history-timeline">'+''.join(story(ev,by) for ev in evs)+'</div><p id="history-empty" hidden>No matching stories. Clear the filters to explore the full timeline.</p></section>'
def gallery_page(data,gallery):
 by={f['slug']:f for f in data};out='<section class="wrap page-intro"><p class="eyebrow">THE SWARAJYA PHOTO JOURNAL</p><h1>Seen through<br><em>a different lens.</em></h1><p class="lead">Gateways, stonework and landscapes. Explore the photographs within each fort’s own story.</p></section><section class="wrap photo-journal">'
 for s,ps in gallery.items():
  if not ps or s not in by:continue
  f=by[s];out+=f'<a class="journal-tile" href="{f["url"]}#fort-gallery">{img(f)}<div><span>{e(f["district"])} · {len(ps)} photos</span><h2>{e(f["name"])} ↗</h2></div></a>'
 return out+'</section>'
def fort(f,data,gallery,events):
 pre='../../';ps=gallery.get(f['slug'],[]);by={a['slug']:a for a in data};related=[ev for ev in events if f['slug'] in ev.get('fort_slugs',[])]
 city=e(f.get('nearest_city') or 'Not yet verified');village=e(f.get('nearest_settlement') or 'Not yet verified')
 out=f'''<div class="wrap breadcrumb"><a href="../../index.html">Home</a> / <a href="../../forts.html">Forts</a> / {e(f['name'])}</div><section class="fort-cinema" data-spotlight><div class="fort-cinema-image">{img(f,pre,True)}</div><div class="fort-cinema-title wrap"><p class="eyebrow">{e(f['district'])} / {e(f['type'])}</p><h1>{e(f['name'])}</h1>{('<p class="marathi-name" lang="mr">'+e(f['marathi_name'])+'</p>') if f.get('marathi_name') else ''}<p>{e(f['significance'])}</p><div class="fort-cinema-bottom"><a href="#fort-gallery" class="outline-button">{'View '+str(len(ps))+' photographs ↘' if ps else 'Photography status ↘'}</a><span>{label(f)}</span></div></div></section><div class="wrap image-credit">{credit(f['image_credit']) if f.get('image_credit') else 'Imagined Sahyadri illustration; a photograph of this fort is not yet available.'}</div>
<div class="wrap fort-intro-grid"><div><p class="eyebrow">YOUR EXPLORATION, AT A GLANCE</p><div class="assessment">{stars(f)}{recommend(f)}</div><p class="intro-reason">{e(f['recommendation_reason'])}</p></div><div class="fort-actions"><a class="button" href="../../maps.html?fort={f['slug']}">View on map ⌖</a><button class="outline-button favorite" data-save="{f['slug']}" aria-pressed="false">♡ Save fort</button><button class="share-button" type="button">Copy link ↗</button><p id="share-status" role="status" aria-live="polite"></p></div></div>
<section class="wrap quick-facts"><dl><div><dt>District</dt><dd>{e(f['district'])}</dd></div><div><dt>Base / nearby village</dt><dd>{village}</dd></div><div><dt>Nearby city</dt><dd>{city}</dd></div><div><dt>Source elevation</dt><dd>{e(f['elevation'] or 'Not documented')}</dd></div></dl><p class="small">{e(f.get('city_method'))}{(' '+str(f['city_distance_km'])+' km to the listed city.') if f.get('city_distance_km') is not None else ''}</p></section>
<div class="wrap"><nav class="detail-jump" aria-label="On this fort page"><a href="#fort-history">The story</a><a href="#fort-gallery">Photographs</a><a href="#fort-architecture">Architecture</a><a href="#trekking">Plan your visit</a><a href="#references">Sources</a></nav></div><div class="wrap fort-editorial"><article><section id="fort-history" class="detail-section"><p class="eyebrow">THE STORY BEHIND THE STONE</p><h2>Why {e(f['name'])}<br><em>matters.</em></h2>'''
 if f['history']:out+='<p class="history-lead">'+e(f['history'])+'</p>'
 else:out+='<blockquote>'+e(f['history_excerpt'])+'</blockquote><p class="small">A short excerpt from the linked source account. A fuller editorial history is still being researched.</p>'
 if f.get('history_insights'):
  insight=f['history_insights'];out+='<details class="history-insights"><summary>'+e(insight['title'])+' <span>＋</span></summary>'+''.join('<p>'+e(t)+'</p>' for t in insight['paragraphs'])+'<p class="small">Research source: <a href="'+e(insight['url'])+'">'+e(insight['source_title'])+'</a> · Reviewed '+e(insight['reviewed'])+'</p></details>'
 if f['aliases']:out+='<p class="alias">Also known as '+e(', '.join(f['aliases']))+'</p>'
 for k in ['shivaji_connection','sambhaji_connection']:
  if f.get(k):out+='<p>'+e(f[k])+'</p>'
 out+='<details class="ruler-history"><summary>Rulers & historical periods <span>＋</span></summary><p>'+e(', '.join(f['rulers']) or 'Individual ruling powers have not been established in this entry.')+'</p>'
 for period in f.get('ruler_periods',[]):out+='<p>'+e(period if isinstance(period,str) else ' · '.join(str(v) for v in period.values()))+'</p>'
 out+='<p class="small">Recorded possession intervals may omit changes of control. Exact uninterrupted durations are not assumed from a ruler’s reign.</p></details></section>'
 if related:out+='<section class="detail-section fort-event-section"><p class="eyebrow">A PLACE WITHIN THE LARGER STORY</p><h2>Turning points.</h2>'+''.join(story(ev,by,pre) for ev in related)+'</section>'
 out+='</article><aside class="visit-card"><p class="eyebrow">A THOUGHTFUL VISIT</p><h2>Before you go.</h2><dl><dt>Source trek duration</dt><dd>'+e(f['duration'] or 'Not documented')+'</dd><dt>Source season advice</dt><dd>'+e(f['best_season'] or 'Check local conditions')+'</dd></dl><a class="button" href="#trekking">Read the route notes ↓</a>'+('<a class="outline-button" href="'+e(f['directions_url'])+'" target="_blank" rel="noopener">Get directions ↗</a>' if f['directions_url'] else '')+'<p class="small">A fort location marks the monument. Confirm the safe approach and current access locally.</p></aside></div>'
 out+='<section id="fort-gallery" class="fort-gallery-section"><div class="wrap">'+heading('A PHOTOGRAPHIC JOURNEY','Look closer. <em>Discover more.</em>')+f'<p class="gallery-intro">{len(ps)} photographs · select an image to explore in the viewer</p><div class="photo-grid cinematic-grid">'
 for i,p in enumerate(ps):
  caption=f['name']+' · '+p.get('caption',p['title'].removeprefix('File:'))+' · '+p.get('artist','')
  out+=f'<figure><button class="gallery-open" data-image="../../{e(p["file"])}" data-caption="{e(caption)}" aria-label="Open photograph {i+1} of {e(f["name"])}"><img src="../../{e(p["thumbnail"])}" srcset="../../{e(p["thumbnail"])} 600w, ../../{e(p["file"])} 1600w" sizes="(max-width:600px) 85vw, (max-width:900px) 50vw, 40vw" width="1600" height="1000" loading="lazy" decoding="async" alt="{e(p.get("caption") or p.get("description") or p["title"])}"><span class="photo-expand" aria-hidden="true">↗</span></button><figcaption>{credit(p)}</figcaption></figure>'
 if not ps:out+='<div class="photography-pending"><span aria-hidden="true">◫</span><h3>This view is still missing.</h3><p>We are researching photographs of this fort. Its source history and visitor information remain available below.</p></div>'
 out+='</div></div></section><div class="wrap fort-bottom-grid"><section id="fort-architecture" class="detail-section"><p class="eyebrow">READING THE REMAINS</p><h2>Architecture &<br><em>fort features.</em></h2><p>Explore features described in the historical source. Their surviving condition and access can vary.</p><div id="fort-layout" class="layout-features">'
 for i,a in enumerate(f['architecture']):out+='<details><summary><span class="feature-number">'+str(i+1).zfill(2)+'</span>'+e(a)+' <span>＋</span></summary><p>'+e(a)+' is recorded in the linked account of '+e(f['name'])+'. <a href="#references">Explore the historical sources ↗</a></p></details>'
 if not f['architecture']:out+='<p>Architectural features await a reliable, fort-specific account.</p>'
 out+='</div><p class="small">Feature inventory only. A surveyed top-down plan is not yet available in this guide.</p></section><section id="trekking" class="detail-section"><p class="eyebrow">KNOW THE APPROACH</p><h2>Plan your<br><em>exploration.</em></h2>'+stars(f)+'<ul>'+''.join('<li>'+e(x)+'</li>' for x in f['difficulty_reasons'])+'</ul><p>'+e(f['how_to_reach'] or 'Detailed routes are not verified. Consult the source guide and confirm access locally.')+'</p><details><summary>Assessment & safety notes <span>＋</span></summary><p>'+e(f['route_assessed'])+'. '+e(f['difficulty_confidence'])+'.</p><p>'+e(f['safety'])+'</p><p class="small">Source review: '+e(f['reviewed'])+'. Stars describe route difficulty; recommendations are separate editorial judgements. No community review counts are displayed.</p></details></section></div>'
 near=[a for a in data if a['district']==f['district'] and a['slug']!=f['slug']]
 out+='<section class="wrap section">'+heading('KEEP THE JOURNEY GOING','More of <em>'+e(f['district'])+'.</em>','All forts','../../forts.html')+'<div class="card-grid">'+''.join(card(a,pre) for a in near[:3])+'</div></section><section id="references" class="wrap detail-section references"><details><summary>Research sources & image credits <span>＋</span></summary><ol>'+''.join('<li><a href="'+e(r['url'])+'">'+e(r['title'])+' ↗</a></li>' for r in f['references'])+'</ol><p class="small">Source review: '+e(f['reviewed'])+'. Coordinates: '+e(f['coordinate_status'])+'.</p><a href="../../sources.html">Research approach and credits ↗</a></details></section>'
 return out
def decorate(body,active,data):
 if active=='Districts' and 'district-tile' in body:
  for d in sorted(set(f['district'] for f in data)):
   candidates=[f for f in data if f['district']==d and f['image_kind']=='photograph']
   if candidates:
    f=next((x for x in candidates if x['recommendation']=='Most Recommended'),candidates[0])
    body=body.replace('<h2>'+e(d)+'</h2>',img(f)+'<h2>'+e(d)+'</h2>')
 if active in ['Our story','About','Contact']:
  f=next(x for x in data if x['slug']=='pratapgad')
  body='<div class="editorial-banner">'+img(f)+'<span>PRATAPGAD / MAHARASHTRA</span></div>'+body
 return body
